[data-workspace-area="conversation"]{background-image:var(--sx-actor),radial-gradient(120% 55% at 50% -12%,color-mix(in srgb,var(--sx-accent) var(--sx-ambient),transparent),transparent 62%)!important;background-size:120px 120px,100% 100%!important;background-position:right 160px top 95px,0 0!important;background-repeat:no-repeat!important}
[data-workspace-area="conversation"]::before{inset:-50px -70px auto auto;width:620px;height:440px;background:var(--sx-dot);-webkit-mask:var(--sx-topo) 50%/100% 100% no-repeat;mask:var(--sx-topo) 50%/100% 100% no-repeat;opacity:.6;transform-origin:60% 40%;animation:sx-breathe 30s var(--sx-inout) infinite alternate}
@keyframes sx-breathe{to{transform:scale(1.06) rotate(1.5deg)}}
:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::before{opacity:1}
[data-workspace-area="conversation"]::after{background:radial-gradient(44% 40% at 74% 10%,color-mix(in srgb,var(--sx-accent) 10%,transparent),transparent 70%);opacity:0}
:root:has(.chat-markdown[data-streaming],.live-tool-shine) [data-workspace-area="conversation"]::after{opacity:1}
[data-slot="sidebar-inner"]::before{content:"";position:absolute;left:-190px;bottom:-130px;width:500px;height:355px;pointer-events:none;background:var(--sx-dot);-webkit-mask:var(--sx-topo) 50%/100% 100% no-repeat;mask:var(--sx-topo) 50%/100% 100% no-repeat;opacity:.55}
@media (prefers-reduced-motion:reduce){[data-workspace-area="conversation"]::before,[data-workspace-area="conversation"]::after,[data-slot="sidebar-inner"]::before{animation:none!important;transition:none!important}h1:has([data-draft-project-trigger])::before{content:none}[data-workspace-area="conversation"],[data-slot="sidebar-inner"]{--sx-actor:none;--sx-actor-2:none;--sx-pc:transparent}}
